<#
  Fix-SlowPhotoUploadBudgetPhones.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  Root cause: the delivery-photos bucket's real limit (checked directly
  in Supabase) is 5MB, but every photo was being force-compressed down to
  an arbitrary 0.8MB target with default (fairly high) iteration settings
  - meaningfully more compression work than the bucket ever actually
  needed, on every single upload, worst of all on the weakest CPUs. And
  there was no timeout: if compression got stuck (a stuck Web Worker, an
  older WebView struggling with a large image - both realistic on a
  budget device), the rider was left staring at "Uploading..." forever
  with no way out.

  Fixed in src\app\send-package\step-2\page.jsx:
    - Skip compression entirely when the photo is already under 1.5MB -
      common on budget-phone cameras, which often shoot smaller/lower-res
      photos than flagship phones to begin with.
    - When compression does run, target 1.5MB (not 0.8MB) with fewer max
      iterations - converges faster since there's real headroom under the
      bucket's actual 5MB limit, at the cost of a slightly larger (still
      well within budget) file.
    - A 12-second timeout wraps the compression call. If it hasn't
      finished by then, stop waiting - upload the original file directly
      instead, as long as it's under the bucket's 5MB limit. Compression
      stops being something that can strand a rider indefinitely.
    - If the original genuinely IS over 5MB and compression couldn't
      bring it down, that's now a clear, specific error message instead
      of an indefinite hang.
    - After 5 seconds of uploading, a reassurance line appears ("This can
      take a bit longer on some phones - still working") so a slow
      device doesn't look frozen while it's genuinely just still working.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  the existing file to .fix-backup-slow-photo-upload\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-SlowPhotoUploadBudgetPhones.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-slow-photo-upload"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Force -Path $destParent | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Force -Path $targetParent | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying slow-photo-upload / budget-phone fix:" -ForegroundColor Cyan

$b64_STEP2 = ""
Write-FileFromBase64 "src\app\send-package\step-2\page.jsx" $b64_STEP2

Write-Host "`nDone. Backup saved under .fix-backup-slow-photo-upload\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then commit, push, and redeploy." -ForegroundColor Cyan
